#include <stdio.h>

#define V 5

int main(void) {
    int g[V][V] = {0};
    int edges[][2] = {{0,1},{0,2},{1,3},{2,3},{3,4}};
    int m = (int)(sizeof(edges) / sizeof(edges[0]));

    /* 无向图：每条边要加两次 */
    for (int i = 0; i < m; i++) {
        int u = edges[i][0], v = edges[i][1];
        g[u][v] = 1;
        g[v][u] = 1;
    }

    printf("邻接矩阵（V=%d）：\n", V);
    printf("     ");
    for (int i = 0; i < V; i++) printf("%d ", i);
    printf("\n");
    for (int i = 0; i < V; i++) {
        int deg = 0;
        printf("%d :  ", i);
        for (int j = 0; j < V; j++) { printf("%d ", g[i][j]); deg += g[i][j]; }
        printf("  度=%d\n", deg);
    }

    int sum = 0;
    for (int i = 0; i < V; i++)
        for (int j = 0; j < V; j++) sum += g[i][j];
    printf("\n无向图边数 = %d（矩阵中 1 的个数 %d 的一半）\n", sum / 2, sum);

    printf("判边 (0,3) 是否存在：%s（O(1) 直接寻址，这是矩阵的最大优势）\n",
           g[0][3] ? "存在" : "不存在");

    printf("\n空间代价：int 矩阵 = %zu 字节；若压缩为 1bit 位图 = %zu 字节\n",
           sizeof(g), (size_t)((V * V + 7) / 8));
    printf("当 V=100000 时，即便 1bit 位图也需约 %.2f GB —— 这就是大规模图不能用矩阵的原因\n",
           (100000.0 * 100000.0 / 8.0) / (1024 * 1024 * 1024));
    return 0;
}
